import math


def bucketize_vectors(vectors, bucket_count):
    if not isinstance(vectors, list):
        raise TypeError("vectors must be a list")
    if isinstance(bucket_count, bool) or not isinstance(bucket_count, int):
        raise TypeError("bucket_count must be an integer")
    if bucket_count <= 0:
        raise ValueError("bucket_count must be positive")
    if not vectors:
        return []

    width = None
    for row in vectors:
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        if not row:
            raise ValueError("rows must not be empty")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("rows must have equal width")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("cells must be numbers")
            if not math.isfinite(value) or value < 0:
                raise ValueError("cells must be finite and non-negative")

    if bucket_count > width:
        raise ValueError("bucket_count exceeds row width")

    result = []
    for row in vectors:
        buckets = [0.0] * bucket_count
        for column, value in enumerate(row):
            buckets[(column + 1) % bucket_count] += value
        result.append(buckets)
    return result

